import pty, os, sys, time, select

user, curpw, newpw = sys.argv[1], sys.argv[2], sys.argv[3]

def run(cmd, responses, timeout=10):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(cmd[0], cmd)
    output = b""
    resp_i = 0
    end = time.time() + timeout
    while time.time() < end:
        r, _, _ = select.select([fd], [], [], 1)
        if fd in r:
            try:
                chunk = os.read(fd, 4096)
            except OSError:
                break
            if not chunk:
                break
            output += chunk
            if resp_i < len(responses):
                os.write(fd, responses[resp_i].encode() + b"\n")
                resp_i += 1
    try:
        os.close(fd)
    except OSError:
        pass
    try:
        os.waitpid(pid, 0)
    except ChildProcessError:
        pass
    return output.decode(errors="replace")

out = run(["sudo", "-n", "-u", user, "--", "passwd"], [curpw, newpw, newpw])
print(out)
